/* PawPaw reference-board presentation. Prices, stock, accounts and orders remain API-owned. */
const ASSET='/static/assets/';
const PRODUCT_ART={
 'hat-dinh-duong-puppycare':'puppycare','thuc-an-meo-catlove':'catlove','pate-royaldog':'royaldog','pate-catmenu':'catmenu','dem-ngu-meo':'pink-bed','bong-day-thung':'rope-ball','do-choi-ca-nhoi-bong':'fish-toy','nha-ngu-meo':'cat-house','dau-goi-pawpaw':'shampoo','day-dat-meo':'harness'
};
function artKey(p){return PRODUCT_ART[p.slug]||PRODUCT_ART[Object.keys(PRODUCT_ART).find(k=>p.name?.toLowerCase().includes(k.split('-').slice(-1)[0]))]||({'🥣':'puppycare','🐟':'catlove','🥫':'royaldog','🍲':'catmenu','🛏️':'pink-bed','🧶':'rope-ball','🐠':'fish-toy','🏠':'cat-house','🧴':'shampoo','🦮':'harness'})[p.emoji]}
function productArt(p,cls=''){const key=artKey(p);return key?`<img class="product-photo ${cls}" src="${ASSET}products/${key}.webp?v=alpha2" alt="${esc(p.name||'Sản phẩm thú cưng')}" loading="lazy">`:`<span class="product-fallback ${cls}">${esc(p.emoji||'◇')}</span>`}
function petArt(name,cls='',alt=''){return `<img class="pet-photo ${cls}" src="${ASSET}${name}.webp" alt="${esc(alt)}" loading="lazy">`}
const ICON_PATHS={paw:'M12 12c-3 0-7 4-7 7 0 4 4 2 7 2s7 2 7-2c0-3-4-7-7-7M5 6v2M10 3v3M16 3v3M21 7v2',cart:'M2 3h3l2 12h12l3-9H6M9 21h.01M18 21h.01',user:'M20 21v-3a8 5 0 0 0-16 0v3M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8',search:'M21 21l-5-5M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',truck:'M1 5h13v12H1zM14 9h5l4 5v3h-9M7 19a2 2 0 1 0-4 0 2 2 0 0 0 4 0M21 19a2 2 0 1 0-4 0 2 2 0 0 0 4 0',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 11l3 3 5-6',refresh:'M3 10a9 9 0 0 1 16-5l2 3M21 3v5h-5M21 14A9 9 0 0 1 5 19l-2-3M3 21v-5h5',headset:'M3 14v-3a9 9 0 0 1 18 0v3M3 12h3v8H3zM18 12h3v8h-3zM18 20c0 2-3 2-6 2',calendar:'M3 5h18v17H3zM3 10h18M7 2v6M17 2v6M7 14h2M13 14h2M7 18h2M13 18h2',heart:'M12 21S1 14 1 7c0-6 8-7 11-1 3-6 11-5 11 1 0 7-11 14-11 14',home:'M2 11L12 2l10 9M5 9v13h5v-8h4v8h5V9',box:'M2 7l10-5 10 5v13l-10 4-10-4zM2 7l10 5 10-5M12 12v12',tag:'M2 2h9l12 12-9 9L2 11zM7 7h.01',chart:'M3 3v19h19M7 17V9M12 17V5M17 17v-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 2h6l1 4 4 1 2 5-3 3 1 4-5 3-3-3-4 1-4-4 2-4-3-3 2-5 4 1z',check:'M4 12l5 5L21 5',mail:'M2 4h20v16H2zM2 5l10 8L22 5',lock:'M5 10h14v12H5zM8 10V6a4 4 0 0 1 8 0v4',phone:'M5 2l5 5-3 3c2 4 3 5 7 7l3-3 5 5c-5 8-23-10-17-17',trash:'M3 6h18M8 6V3h8v3M6 6l1 16h10l1-16M10 10v8M14 10v8',edit:'M4 15L16 3l5 5L9 20l-6 1zM13 6l5 5',filter:'M2 3h20l-8 9v8l-4 2V12z',pin:'M12 22s8-8 8-13a8 8 0 1 0-16 0c0 5 8 13 8 13M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',gift:'M2 9h20v5H2zM4 14v8h16v-8M12 9v13M12 9C1 9 6-3 12 9c6-12 11 0 0 0',bell:'M4 17h16l-2-4V8a6 6 0 0 0-12 0v5zM10 21h4'};
function icon(name,cls=''){if(name==='paw')return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><ellipse cx="5" cy="8" rx="2.6" ry="3.5" transform="rotate(-25 5 8)"/><ellipse cx="10" cy="4.5" rx="2.5" ry="3.4"/><ellipse cx="16" cy="4.8" rx="2.5" ry="3.4" transform="rotate(15 16 5)"/><ellipse cx="20.5" cy="10" rx="2.5" ry="3.4" transform="rotate(30 20 10)"/><path d="M12 10c-2.5 0-3.5 3-5.5 5C2 20 6 23 10 21c1.3-.6 2.7-.6 4 0 4 2 8-1 3.5-6C15.5 13 14.5 10 12 10"/></svg>`;return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICON_PATHS[name]||ICON_PATHS.paw}"/></svg>`}
function brand(){return link('/',`${icon('paw','brand-paw')}<span>PawPaw<small>Pet Shop</small></span>`,'brand')}
function bread(label){return `<div class="breadcrumb">${link('/',icon('home')+' Trang chủ')}<span>›</span>${label}</div>`}
function titleRow(title,sub='',i='paw'){return `<div class="page-heading"><h1>${icon(i)}${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function trust(){return `<section class="trust-row">${[['truck','Miễn phí giao hàng',`Đơn từ ${money(STATE.freeShippingFrom)}`],['shield','Sản phẩm chính hãng','An toàn, chất lượng'],['refresh','Đổi trả 7 ngày','Nhanh chóng, tiện lợi'],['headset','Tư vấn tận tâm','Hỗ trợ chăm sóc thú cưng']].map(x=>`<div>${icon(x[0])}<section><b>${x[1]}</b><small>${x[2]}</small></section></div>`).join('')}</section>`}
header=function(admin=false){if(admin)return `<header class="admin-top">${brand()}<label class="admin-search">${icon('search')}<input id="admin-search" placeholder="Tìm kiếm trong quản trị (đơn hàng, sản phẩm, khách hàng...)"></label><div class="admin-user">${icon('bell')}${petArt('pet-duo','avatar-pet')}<span>Admin<small>Quản trị viên⌄</small></span><button class="icon-button" data-action="logout" aria-label="Đăng xuất">↪</button></div></header>`;return `<div class="utility"><span>${icon('truck')}Miễn phí giao hàng toàn quốc cho đơn từ ${money(STATE.freeShippingFrom)}</span><span>${icon('shield')}Hàng chính hãng, an toàn cho thú cưng</span><span>${icon('refresh')}Đổi trả dễ dàng trong 7 ngày</span></div><header class="shop-header"><button type="button" class="mobile-menu-button" data-menu-toggle aria-label="Mở menu" aria-expanded="false"><span></span><span></span><span></span></button>${brand()}<label class="search">${icon('search')}<input id="search-box" aria-label="Tìm kiếm sản phẩm" placeholder="Tìm kiếm sản phẩm, thương hiệu, dịch vụ..."><button data-action="search" aria-label="Tìm kiếm">${icon('search')}</button></label><div class="header-actions">${link(STATE.user?'/account':'/login',`${icon('user')}<span>${STATE.user?esc(STATE.user.full_name):'Đăng nhập'}<small>${STATE.user?'Tài khoản':'Đăng ký'}</small>`)}${link('/cart',`${icon('cart')}<span>Giỏ hàng<small>(${countCart()})</small></span><b class="cart-badge">${countCart()}</b>`)}</div><nav class="main-nav" id="main-navigation" aria-label="Danh mục chính">${[['/','Trang chủ'],['/shop','Thú cưng⌄'],['/shop?category=Thức%20ăn','Thức ăn⌄'],['/shop?category=Phụ%20kiện','Phụ kiện⌄'],['/services','Dịch vụ⌄'],['/shop?sort=newest','Thương hiệu⌄'],['/shop?sort=popular','Khuyến mãi']].map(x=>link(x[0],x[1],location.pathname===x[0]?'nav-active':'')).join('')}${link('/services',icon('calendar')+' Đặt lịch dịch vụ','book-link')}</nav></header>`};
shell=function(content){return `<div class="site-frame">${header()}<main class="store-main">${content}</main></div>${mobileNavigation()}`};
productCard=function(p){return `<article class="product-card" data-product-id="${p.id}"><button class="heart ${STATE.favorite.has(p.id)?'liked':''}" data-favorite="${p.id}" aria-label="Yêu thích">${icon('heart')}</button>${p.featured?'<span class="sale-pill">Bán chạy</span>':''}<a class="product-image" href="/product/${encodeURIComponent(p.slug)}" data-route>${productArt(p)}</a><a class="product-name" href="/product/${encodeURIComponent(p.slug)}" data-route>${esc(p.name)}</a><div class="product-quality">${icon('shield')} Sản phẩm chính hãng</div><div class="price">${money(p.price_vnd)} ${p.compare_price_vnd?`<del>${money(p.compare_price_vnd)}</del><small class="discount">-${Math.round((1-p.price_vnd/p.compare_price_vnd)*100)}%</small>`:''}</div><small class="availability ${p.stock?'':'danger'}">${icon('pin')}${p.stock?'Còn hàng':'Tạm hết hàng'}</small><button class="btn btn-green btn-small full" data-add="${p.id}" ${p.stock?'':'disabled'}>${icon('cart')} Thêm vào giỏ</button></article>`};
home=async function(){const ps=await getProducts('?limit=12');const preferred=['hat-dinh-duong-puppycare','thuc-an-meo-catlove','bong-day-thung','dem-ngu-meo'];const featured=preferred.map(slug=>ps.find(p=>p.slug===slug)).filter(Boolean);for(const p of ps){if(featured.length>=4)break;if(!featured.some(x=>x.id===p.id))featured.push(p)}return shell(`<section class="hero"><div class="hero-copy"><h1>Bạn thân bốn chân,<br><em>niềm vui mỗi ngày</em></h1><p>Thức ăn, phụ kiện và dịch vụ chăm sóc thú cưng<br>chính hãng, an toàn và tận tâm tại PawPaw.</p>${link('/shop','Khám phá ngay →','btn btn-coral')}<span class="hero-doodle">♡</span><span class="hero-paw-a">${icon('paw')}</span><span class="hero-paw-b">${icon('paw')}</span></div><div class="hero-art" role="img" aria-label="Cún con và mèo nằm trên đệm êm"></div></section>${trust()}<section class="section"><div class="section-head"><h2>${icon('paw')}Danh mục sản phẩm</h2>${link('/shop','Xem tất cả →','text-link')}</div><div class="category-grid">${[['pet-duo','Thú cưng','Chó, mèo, thỏ...','/shop'],['puppycare-lifestyle','Thức ăn','Hạt, pate, snack...','/shop?category=Thức%20ăn'],['products/pink-bed','Phụ kiện','Chuồng, đệm, đồ chơi...','/shop?category=Phụ%20kiện'],['grooming','Dịch vụ','Tắm, cắt tỉa, spa...','/services']].map(x=>link(x[3],`${petArt(x[0])}<b>${x[1]}</b><small>${x[2]}</small>`,'category-tile')).join('')}</div></section><section class="section"><div class="section-head"><h2>${icon('paw')}Sản phẩm bán chạy</h2>${link('/shop','Xem thêm →','text-link')}</div><div class="product-grid home-products">${featured.map(productCard).join('')}</div></section><section class="care-banner">${petArt('grooming')}<div><h2>Đặt lịch dịch vụ tại PawPaw</h2><p>Chăm sóc toàn diện cho thú cưng<br>bởi đội ngũ chuyên nghiệp, thân thiện.</p><div class="care-services"><span>${icon('paw')}Tắm & Spa</span><span>✂ Cắt tỉa lông</span><span>${icon('shield')}Khám thú y</span></div></div>${link('/services','Đặt lịch ngay →','btn btn-coral')}</section>`)};
function catalogMaxPrice(){const value=new URLSearchParams(location.search).get('maxPrice');const number=value===null?1000000:Number(value);return Number.isFinite(number)?Math.min(1000000,Math.max(0,number)):1000000}
function filterPanel(favoritesOnly=false){const category=new URLSearchParams(location.search).get('category')||'Tất cả';return `<aside class="filters card" id="catalog-filters"><button type="button" class="filter-close" data-filter-toggle aria-label="Đóng bộ lọc">×</button><h3>${icon('filter')}${favoritesOnly?'Bộ lọc danh sách':'Bộ lọc'}<button class="text-link" data-action="clear-filters">Xóa tất cả</button></h3><b>Danh mục</b>${CATEGORIES.map(c=>`<label><input type="radio" name="category-filter" value="${esc(c)}" ${c===category?'checked':''}>${esc(c)}</label>`).join('')}<hr><b>Khoảng giá</b><input type="range" min="0" max="1000000" value="${catalogMaxPrice()}" aria-label="Giá tối đa" id="price-filter"><div class="price-bounds"><span>Từ<br><b>0₫</b></span><span>Đến<br><b id="price-filter-label">${money(catalogMaxPrice())}</b></span></div><hr><b>Thương hiệu</b>${['PuppyCare','CatLove','RoyalDog','MeowLine','PetBest'].map(x=>`<label><input type="checkbox" name="brand-filter" value="${x}" ${new URLSearchParams(location.search).getAll('brand').includes(x)?'checked':''}>${x}</label>`).join('')}<hr><b>Loại thú cưng</b>${['Tất cả','Chó','Mèo','Thỏ'].map(x=>`<label><input type="radio" name="species-filter" value="${x}" ${x===(new URLSearchParams(location.search).get('species')||'Tất cả')?'checked':''}>${x}</label>`).join('')}<button class="btn btn-green full" data-action="apply-filters">Áp dụng</button></aside>`}
shop=async function(){const params=new URLSearchParams(location.search);const ps=await getProducts('?'+params);return shell(`${bread('Thức ăn cho thú cưng')}<div class="shop-layout">${filterPanel()}<section><div class="shop-title"><button type="button" class="btn btn-light mobile-filter-button" data-filter-toggle aria-controls="catalog-filters" aria-expanded="false">${icon('filter')}Bộ lọc</button><div><h1>${icon('paw')}${esc(params.get('category')||'Sản phẩm cho thú cưng')}</h1><p>Có ${ps.length} sản phẩm</p></div><select id="sort-products">${[['popular','Phổ biến nhất'],['price-asc','Giá tăng dần'],['price-desc','Giá giảm dần'],['newest','Mới nhất']].map(x=>`<option value="${x[0]}" ${params.get('sort')===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="product-grid catalog-products">${ps.map(productCard).join('')||'<p class="empty-state">Không tìm thấy sản phẩm phù hợp.</p>'}</div><div class="pagination"><span>Hiển thị ${ps.length} sản phẩm</span><b>1</b></div></section></div>`)};
productPage=async function(slug){let p;try{p=await api('/api/products/'+encodeURIComponent(slug));STATE.products=[p,...STATE.products.filter(x=>x.id!==p.id)]}catch(e){return shell(bread('Sản phẩm')+`<p class="empty-state">${esc(e.message)}</p>`)}return shell(`${bread(esc(p.name))}<section class="product-detail card"><div class="detail-art"><div class="thumbs"><button type="button" data-gallery-src="${ASSET}products/${artKey(p)}.webp?v=alpha2" aria-label="Ảnh bao bì">${productArt(p)}</button>${p.slug==='hat-dinh-duong-puppycare'?`<button type="button" data-gallery-src="${ASSET}puppycare-lifestyle.webp" aria-label="Ảnh sản phẩm cùng thú cưng">${petArt('puppycare-lifestyle')}</button>`:''}</div><div class="product-stage">${p.slug==='hat-dinh-duong-puppycare'?petArt('puppycare-lifestyle','detail-lifestyle',p.name):productArt(p)}<span class="stage-paw">${icon('paw')}</span></div></div><div class="detail-info"><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p><div class="detail-quality">${icon('shield')} Hàng chính hãng <span>· Dành cho ${esc(p.species)}</span></div><div class="detail-price">${money(p.price_vnd)} ${p.compare_price_vnd?`<del>${money(p.compare_price_vnd)}</del><small class="discount">-${Math.round((1-p.price_vnd/p.compare_price_vnd)*100)}%</small>`:''}</div><p class="stock-note">${p.stock?'Còn hàng · '+p.stock+' sản phẩm':'Tạm hết hàng'}</p><label>Số lượng:</label><div class="qty-row"><div class="stepper"><button data-qty="-1" aria-label="Giảm số lượng">−</button><b id="product-qty">1</b><button data-qty="1" aria-label="Tăng số lượng">+</button></div></div><button class="btn btn-green full" data-add="${p.id}" ${p.stock?'':'disabled'}>${icon('cart')}Thêm vào giỏ hàng</button><div class="buy-line"><button class="btn btn-coral full" data-add="${p.id}" data-buy="true" ${p.stock?'':'disabled'}>Mua ngay</button><button class="btn btn-light" data-favorite="${p.id}" aria-label="Yêu thích">${icon('heart')}</button></div></div></section>${trust()}<section class="card product-description"><div class="tabs"><b>Mô tả sản phẩm</b><span>Thông tin sản phẩm</span></div><div class="description-columns"><div><h3>Mô tả sản phẩm</h3><p>${esc(p.description)}</p>${productArt(p)}</div><div><h3>Ưu điểm nổi bật</h3><p>✓ Sản phẩm chính hãng</p><p>✓ Phù hợp cho ${esc(p.species.toLowerCase())}</p><p>✓ Đổi trả theo chính sách cửa hàng</p><p>✓ Tư vấn chăm sóc tận tâm</p></div></div></section>`)};
function cartItems(){return STATE.cart.map(ci=>({...STATE.products.find(p=>p.id===ci.productId),id:ci.productId,name:ci.name,price_vnd:ci.price,emoji:ci.emoji,quantity:ci.quantity}))}
cart=function(){const items=cartItems(),sub=items.reduce((s,p)=>s+p.price_vnd*p.quantity,0),ship=sub>=STATE.freeShippingFrom||!sub?0:30000;return shell(`${bread('Giỏ hàng')}${titleRow(`Giỏ hàng của bạn <small>(${countCart()} sản phẩm)</small>`,'','cart')}${items.length?`<section class="card cart-list"><div class="cart-head"><label><input type="checkbox" checked disabled>Chọn tất cả</label><button class="text-link" data-action="clear-cart">${icon('trash')}Xóa giỏ hàng</button></div><div class="cart-table-head"><span>Sản phẩm</span><span>Đơn giá</span><span>Số lượng</span><span>Thành tiền</span></div>${items.map(p=>`<div class="cart-item">${productArt(p)}<div class="cart-name"><b>${esc(p.name)}</b><small>● Còn hàng</small></div><strong>${money(p.price_vnd)}</strong><div class="stepper"><button data-cart-qty="${p.id}" data-delta="-1" aria-label="Giảm số lượng">−</button>${p.quantity}<button data-cart-qty="${p.id}" data-delta="1" aria-label="Tăng số lượng">+</button></div><b>${money(p.price_vnd*p.quantity)}</b><button class="remove" data-remove="${p.id}" aria-label="Xóa sản phẩm">${icon('trash')}</button></div>`).join('')}</section><div class="cart-bottom"><div><section class="card coupon-card"><h3>${icon('gift')}Mã giảm giá</h3><div class="coupon"><input id="coupon" placeholder="Nhập mã giảm giá..."><button class="btn btn-green" data-action="coupon">Áp dụng</button></div><p class="coupon-hint"><b>PAWPAW10</b> Giảm 10% theo điều kiện của shop</p></section><section class="card shipping-card"><h3>${icon('truck')}Ước tính phí giao hàng</h3><select aria-label="Tỉnh thành"><option>Hà Nội</option><option>Đà Nẵng</option><option>TP. Hồ Chí Minh</option></select><p>${icon('truck')}Phí giao hàng: <b>${money(ship)}</b></p></section></div><aside class="card summary"><div><span>Tạm tính (${items.length} sản phẩm)</span><b>${money(sub)}</b></div><div><span>Giảm giá</span><span>Xác nhận khi đặt hàng</span></div><div><span>Phí giao hàng</span><b>${money(ship)}</b></div><div class="summary-total"><span>Tổng thanh toán</span><b>${money(sub+ship)}</b></div>${link('/checkout','Tiến hành thanh toán →','btn btn-coral full')}${link('/shop','↩ Tiếp tục mua sắm','text-link')}</aside></div>`:`<section class="empty-state card">${icon('cart')}<h2>Giỏ hàng đang trống</h2>${link('/shop','Khám phá sản phẩm','btn btn-green')}</section>`}`)};
checkout=function(){if(!STATE.cart.length)return cart();const items=cartItems(),sub=items.reduce((n,p)=>n+p.price_vnd*p.quantity,0),shipping=sub>=STATE.freeShippingFrom?0:30000;return shell(`${bread('Giỏ hàng　›　Thanh toán')}${titleRow('Thanh toán đặt hàng','','cart')}<ol class="checkout-progress"><li class="complete"><b>1</b>Giỏ hàng</li><li class="current"><b>2</b>Thông tin giao hàng</li><li><b>3</b>Thanh toán & Đặt hàng</li></ol><form id="checkout-form" class="checkout-layout"><section class="card form-card"><h3>${icon('box')}Thông tin giao hàng</h3><div class="form-grid"><label>Người nhận *<input name="name" autocomplete="name" value="${esc(STATE.user?.full_name||'')}" required placeholder="Họ và tên người nhận"></label><label>Số điện thoại *<input name="phone" autocomplete="tel" inputmode="tel" value="${esc(STATE.user?.phone||'')}" required placeholder="Số điện thoại liên hệ"></label><label class="wide">Email<input name="email" type="email" autocomplete="email" value="${esc(STATE.user?.email||'')}" placeholder="Email nhận thông tin đơn hàng"></label><label>Tỉnh / Thành phố *<select name="city" required><option>Hà Nội</option><option>Đà Nẵng</option><option>TP. Hồ Chí Minh</option><option>Tỉnh / thành phố khác</option></select></label><label>Quận / Huyện<input name="district" autocomplete="address-level2" placeholder="Quận / Huyện"></label><label class="wide">Địa chỉ nhận hàng *<input name="address" autocomplete="street-address" required placeholder="Số nhà, tên đường, phường / xã"></label><label class="wide">Ghi chú (tùy chọn)<textarea name="note" rows="2" placeholder="Ví dụ: Giao giờ hành chính, gọi trước khi giao..."></textarea></label></div><h3>${icon('truck')}Phương thức giao hàng</h3><label class="delivery-option"><input type="radio" name="shipping" checked value="standard"><span><b>Giao tiêu chuẩn</b><small>Cửa hàng sẽ liên hệ xác nhận thời gian giao</small></span><strong>${shipping?money(shipping):'Miễn phí'}</strong></label><h3>${icon('shield')}Phương thức thanh toán</h3><label class="delivery-option"><input type="radio" name="payment" checked value="cod"><span><b>Thanh toán khi nhận hàng (COD)</b><small>Thanh toán khi bạn nhận được hàng</small></span></label><label class="delivery-option disabled"><input type="radio" disabled><span><b>Thanh toán qua VNPAY / MoMo</b><small>Chưa kết nối cổng thanh toán</small></span></label><label class="delivery-option disabled"><input type="radio" disabled><span><b>Thẻ ngân hàng quốc tế</b><small>Chưa kết nối cổng thanh toán</small></span></label></section><aside class="card summary checkout-summary"><h3>Đơn hàng của bạn <small>(${items.length} sản phẩm)</small></h3><div class="checkout-items">${items.map(p=>`<div class="checkout-line">${productArt(p)}<span>${esc(p.name)}<small>× ${p.quantity}</small></span><b>${money(p.price_vnd*p.quantity)}</b></div>`).join('')}</div><div><span>Tạm tính</span><b>${money(sub)}</b></div><div><span>Giảm giá</span><small>Xác nhận khi đặt hàng</small></div><div><span>Phí giao hàng</span><b>${money(shipping)}</b></div><div class="summary-total"><span>Tổng thanh toán</span><b>${money(sub+shipping)}</b></div><button class="btn btn-coral full" type="submit">Đặt hàng (${money(sub+shipping)})</button><p class="safe-note">${icon('lock')}Thông tin của bạn được bảo mật và an toàn.</p></aside></form>`)};
function authField(prefix,name,label,type='text',autocomplete='',required=true){
  const id=`${prefix}-${name}`,symbol=type==='email'?'mail':type==='password'?'lock':type==='tel'?'phone':'user';
  return `<div class="auth-field"><label for="${id}">${label}</label><div class="input-icon">${icon(symbol)}<input id="${id}" name="${name}" type="${type}" ${autocomplete?`autocomplete="${autocomplete}"`:''} ${required?'required':''} ${prefix==='signup'&&type==='password'?'minlength="10"':''} placeholder="${label}" ${type==='tel'?'inputmode="tel"':''}>${type==='password'?'<button type="button" data-password-toggle aria-label="Hiện mật khẩu" aria-pressed="false">◉</button>':''}</div></div>`;
}
function loginForm(){return `<form id="login-form" class="card auth-form"><h2>${icon('paw')}Đăng nhập</h2><p class="auth-intro">Chào mừng bạn trở lại với PawPaw.</p>${authField('login','email','Email','email','username')}${authField('login','password','Mật khẩu','password','current-password')}<div class="remember"><label><input type="checkbox" checked>Ghi nhớ đăng nhập</label><button type="button" class="text-link" data-unavailable="Vui lòng liên hệ cửa hàng để được hỗ trợ đặt lại mật khẩu.">Quên mật khẩu?</button></div><button class="btn btn-coral full" type="submit">Đăng nhập</button><div class="or-divider">Hoặc đăng nhập với</div>${[['G','Google'],['f','Facebook'],['●','Apple']].map(x=>`<button type="button" class="social-login" data-unavailable="Đăng nhập ${x[1]} chưa được kết nối. Bạn có thể đăng nhập bằng email."><b>${x[0]}</b>Đăng nhập với ${x[1]}</button>`).join('')}<p class="auth-bottom">Chưa có tài khoản? ${link('/register','Đăng ký ngay','text-link')}</p></form>`}
function registrationForm(){return `<form id="register-form" class="card auth-form"><h2>${icon('paw')}Tạo tài khoản mới</h2><p class="auth-intro">Tham gia PawPaw để mua sắm và chăm sóc bé yêu thuận tiện hơn.</p>${authField('signup','fullName','Họ và tên','text','name')}${authField('signup','email','Email','email','email')}${authField('signup','phone','Số điện thoại','tel','tel',false)}${authField('signup','password','Mật khẩu','password','new-password')}<small class="password-hint">Sử dụng tối thiểu 10 ký tự.</small>${authField('signup','confirmPassword','Xác nhận mật khẩu','password','new-password')}<label class="terms"><input type="checkbox" required><span>Tôi đồng ý với Điều khoản sử dụng và Chính sách bảo mật của PawPaw Pet Shop.</span></label><button class="btn btn-coral full" type="submit">Tạo tài khoản</button><p class="auth-bottom">Đã có tài khoản? ${link('/login','Đăng nhập ngay','text-link')}</p></form>`}
function authPage(){const mode=location.pathname==='/register'?'register':'login';return shell(`${bread(mode==='register'?'Tạo tài khoản':'Đăng nhập')}<section class="auth-board" data-auth-mode="${mode}"><div class="auth-art"><h2>Chào mừng bạn<br><em>đến với PawPaw!</em></h2><p>Mua sắm nhanh hơn, theo dõi đơn hàng và chăm sóc bé yêu mỗi ngày.</p>${petArt('pet-duo','auth-pets')}<div class="auth-benefits">${[['truck','Mua sắm tiện lợi','Lưu thông tin, đặt hàng nhanh'],['gift','Ưu đãi riêng','Nhận ưu đãi dành cho thành viên'],['paw','Chăm sóc bé yêu','Đặt lịch dịch vụ thuận tiện']].map(x=>`<div>${icon(x[0])}<section><b>${x[1]}</b><small>${x[2]}</small></section></div>`).join('')}</div></div><nav class="auth-mobile-tabs" aria-label="Đăng nhập hoặc đăng ký">${link('/login','Đăng nhập',mode==='login'?'active':'')}${link('/register','Đăng ký',mode==='register'?'active':'')}</nav>${loginForm()}${registrationForm()}</section>`)}
account=function(){if(!STATE.user)return authPage();return shell(`${bread('Tài khoản của tôi')}<div class="account-layout"><aside class="card account-nav"><h2>${icon('user')}Tài khoản của tôi</h2><div class="account-identity"><div class="user-avatar big">${esc(STATE.user.full_name?.[0]||'A')}</div><section><b>${esc(STATE.user.full_name)}</b><small>Thành viên PawPaw</small></section></div>${[['home','Tổng quan','#account-overview'],['box','Đơn hàng của tôi','#account-orders'],['paw','Thú cưng của tôi','#account-pets'],['heart','Sản phẩm yêu thích','/favorites'],['gift','Ưu đãi & Mã giảm giá','/shop'],['calendar','Đặt lịch dịch vụ','/services'],['user','Thông tin tài khoản','#account-info']].map(x=>x[2].startsWith('#')?`<a href="${x[2]}">${icon(x[0])}${x[1]}</a>`:link(x[2],icon(x[0])+x[1])).join('')}<button data-action="logout">↪ Đăng xuất</button></aside><section class="account-content" id="account-overview"><div class="card"><h2>Đơn hàng của tôi</h2><div class="account-tabs" aria-label="Lọc đơn hàng">${[["","Tất cả"],["pending","Chờ xác nhận"],["shipping","Đang giao"],["delivered","Đã giao"],["cancelled","Đã hủy"]].map(([status,label])=>`<button type="button" data-account-status="${status}" aria-pressed="${status===''}" class="${status===''?'active':''}">${label}</button>`).join('')}</div><div id="account-orders">Đang tải đơn hàng...</div></div><section class="card" id="account-pets"><div class="section-head"><h2>${icon('paw')}Thú cưng của tôi</h2></div><div class="pet-profiles"><p>Thêm hồ sơ thú cưng khi tính năng được kết nối.</p><button class="pet-profile" data-action="pet-add">＋ Thêm thú cưng</button></div></section><section class="card" id="account-info"><h2>${icon('user')}Thông tin tài khoản</h2><p>${esc(STATE.user.full_name)}</p><p>${esc(STATE.user.email)}</p><p>${esc(STATE.user.phone||'Chưa có số điện thoại')}</p></section></section></div>`)};
register=authPage;
services=function(){return shell(`${bread('Dịch vụ　›　Đặt lịch dịch vụ')}${titleRow('Đặt lịch dịch vụ','Chọn dịch vụ, thú cưng, thời gian phù hợp cho bé yêu nhé!','calendar')}<form id="booking-form" class="booking-board"><div><section class="card booking-section"><h3><b class="step-number">1</b>Chọn dịch vụ</h3><label class="service-choice"><input type="radio" name="serviceType" value="grooming" checked>${petArt('grooming')}<section><h3>Spa & Grooming</h3><b>(tắm, vệ sinh, cắt tỉa lông)</b><p>Tắm sạch, sấy khô, vệ sinh tai – móng – tuyến hôi và cắt tỉa lông theo yêu cầu.</p><strong>Từ 149.000₫</strong></section></label><label class="service-choice"><input type="radio" name="serviceType" value="vet">${petArt('vet-cat')}<section><h3>Tư vấn thú y</h3><b>(khám & tư vấn sức khỏe)</b><p>Khám tổng quát, tư vấn dinh dưỡng, phòng bệnh và chăm sóc định kỳ.</p><strong>Từ 99.000₫</strong></section></label></section><section class="card booking-section"><h3><b class="step-number">2</b>Chọn thú cưng</h3><div class="form-grid"><label>Tên thú cưng<input name="petName" placeholder="Tên bé yêu" required></label><label>Loài<select name="petSpecies"><option>Chó</option><option>Mèo</option><option>Thỏ</option></select></label></div></section></div><div><section class="card booking-section"><h3><b class="step-number">3</b>Chọn ngày và giờ</h3><label>Ngày hẹn<input name="serviceDate" type="date" required min="${new Date().toLocaleDateString('en-CA')}"></label><p>Khung giờ trống</p><div class="time-slots">${['08:00','09:00','10:00','11:00','13:00','14:00','15:00','16:00'].map((t,i)=>`<label><input type="radio" name="timeSlot" value="${t}" ${i===2?'checked':''}><span>${t}</span></label>`).join('')}</div></section><section class="card booking-section"><h3><b class="step-number">4</b>Thông tin liên hệ</h3><label>Họ tên chủ nuôi<input name="ownerName" required value="${esc(STATE.user?.full_name||'')}" placeholder="Họ và tên của bạn"></label><label>Số điện thoại<input name="phone" required value="${esc(STATE.user?.phone||'')}" placeholder="Số điện thoại liên hệ"></label><div class="staff-note">${petArt('staff')}${icon('user')}Đội ngũ PawPaw sẽ gọi xác nhận nhân viên và lịch hẹn phù hợp.</div></section></div><aside><section class="card booking-section booking-summary"><h3>${icon('paw')}Thông tin đặt lịch</h3><dl><div><dt>Dịch vụ</dt><dd id="booking-service-label">Spa & Grooming</dd></div><div><dt>Ngày hẹn</dt><dd id="booking-date-label">Chưa chọn</dd></div><div><dt>Thời gian</dt><dd id="booking-time-label">10:00</dd></div></dl><div class="summary-total"><span>Chi phí dự kiến</span><b id="booking-price">149.000₫</b></div></section><section class="card booking-section"><label>Ghi chú cho cửa hàng<textarea name="note" rows="4" placeholder="Ví dụ: Bé hơi nhát, mong nhẹ nhàng nhé..."></textarea></label><button class="btn btn-coral full">${icon('calendar')}Xác nhận đặt lịch</button></section></aside></form>`)};
favorites=async function(){const all=await getProducts();const ps=all.filter(p=>STATE.favorite.has(p.id));return shell(`${bread('Sản phẩm yêu thích')}<section class="decorated-heading">${titleRow('Sản phẩm yêu thích','Danh sách sản phẩm bạn đã lưu. Thêm vào giỏ ngay để không bỏ lỡ nhé!','heart')}<button class="btn btn-light" data-action="share-favorites">↗ Chia sẻ danh sách</button>${petArt('pet-blanket')}</section><div class="shop-layout">${filterPanel(true)}<section><div class="shop-title"><button type="button" class="btn btn-light mobile-filter-button" data-filter-toggle aria-controls="catalog-filters" aria-expanded="false">${icon('filter')}Bộ lọc</button><p>Có ${ps.length} sản phẩm trong danh sách yêu thích</p></div><div class="product-grid catalog-products">${ps.map(productCard).join('')||'<div class="empty-state card">Bạn chưa lưu sản phẩm nào. Nhấn trái tim ở sản phẩm để thêm vào đây.</div>'}</div></section></div>`)};
support=function(){return shell(`${bread('Trung tâm hỗ trợ')}<section class="decorated-heading support-heading">${titleRow('Trung tâm hỗ trợ','Chúng tôi luôn sẵn sàng đồng hành và giải đáp mọi thắc mắc của bạn<br>về mua sắm, đơn hàng, sản phẩm và dịch vụ cho thú cưng.','headset')}${petArt('pet-blanket')}</section><label class="support-search">${icon('search')}<input id="faq-search" placeholder="Tìm kiếm câu hỏi, hướng dẫn, chính sách..."><button class="btn btn-green" type="button" data-faq-search>Tìm kiếm</button></label><div class="support-board"><aside class="card support-nav"><h3>${icon('box')}Danh mục hỗ trợ</h3>${[['headset','Câu hỏi thường gặp (FAQ)'],['cart','Hướng dẫn đặt hàng'],['truck','Giao hàng & vận chuyển'],['refresh','Đổi trả & hoàn tiền'],['shield','Thanh toán'],['lock','Tài khoản & bảo mật'],['paw','Sản phẩm & dịch vụ'],['gift','Chương trình ưu đãi']].map((x,i)=>`<a href="${i===3?'#return-request':'#faq-list'}">${icon(x[0])}${x[1]}</a>`).join('')}</aside><div><div class="support-upper"><section class="card"><h2>${icon('heart')}Câu hỏi thường gặp</h2><div id="faq-list"></div></section><section class="card need-help"><h2>${icon('headset')}Cần hỗ trợ thêm?</h2><p>Đội ngũ PawPaw luôn sẵn sàng<br>hỗ trợ bạn nhanh chóng!</p><a href="tel:1900636282" class="btn btn-coral">${icon('phone')}Liên hệ tư vấn</a>${petArt('pet-blanket')}</section></div><div class="support-lower"><section class="card"><h3>${icon('paw')}Hướng dẫn & chính sách nổi bật</h3><div class="policy-tiles"><a href="#faq-list">${icon('truck')}<b>Hướng dẫn giao hàng</b><p>Thời gian, phí vận chuyển và khu vực giao hàng</p></a><a href="#return-request">${icon('refresh')}<b>Hướng dẫn đổi trả</b><p>Điều kiện, quy trình và thời gian hoàn tiền</p></a></div></section><section class="card"><h3>Tra cứu đơn hàng</h3><form id="lookup-form"><input name="code" placeholder="Nhập mã đơn hàng PP..." required><input name="phone" placeholder="Số điện thoại đặt hàng" required><button class="btn btn-green full">${icon('search')}Tra cứu</button></form><div id="order-result"></div></section><section class="card"><h3>${icon('phone')}Liên hệ với PawPaw</h3><p>Hotline: 1900 636 282<br><small>8:00 – 21:00, tất cả các ngày</small></p><p>Email: support@pawpaw.vn</p></section></div><section class="card return-card" id="return-request"><h3>${icon('refresh')}Yêu cầu đổi trả / hoàn hàng</h3><form id="return-form" class="form-grid"><label>Mã đơn hàng<input name="orderCode" required></label><label>Số điện thoại<input name="phone" required></label><label>Lý do<select name="reason"><option>Sản phẩm lỗi / hư hỏng</option><option>Giao sai sản phẩm</option><option>Đổi ý / không còn nhu cầu</option></select></label><label>Mô tả thêm<input name="details"></label><button class="btn btn-green">Gửi yêu cầu</button></form></section></div></div>`)};
adminShell=function(content,page){const nav=[['/admin','home','Tổng quan'],['/admin/orders','cart','Đơn hàng'],['/admin/products','box','Sản phẩm'],['/admin/inventory','home','Kho hàng'],['/admin/customers','user','Khách hàng'],['/admin/promotions','tag','Khuyến mãi'],['/admin/appointments','calendar','Dịch vụ & Lịch hẹn'],['/admin/reports','chart','Báo cáo'],['/admin/settings','settings','Cài đặt']];return `<div class="admin-app">${header(true)}<aside class="admin-sidebar"><div class="admin-badge">${petArt('grooming')}<b>Admin PawPaw</b><small>Quản trị viên</small></div>${nav.map(x=>link(x[0],icon(x[1])+x[2],`admin-link ${page===x[0]?'active':''}`)).join('')}${petArt('mascot','sidebar-mascot')}<div class="sidebar-bottom">${link('/','↩ Về cửa hàng')}</div></aside><main class="admin-main"><div class="admin-content">${content}</div></main></div>`};
const baseProductTable=productTable;
productTable=function(rows,inventory){let html=baseProductTable(rows,inventory);for(const p of rows)html=html.replace(`${esc(p.emoji)} <b>${esc(p.name)}</b>`,`${productArt(p)}<b>${esc(p.name)}</b>`);return html};
const baseCustomerTable=customerTable;
customerTable=function(rows){let html=baseCustomerTable(rows);for(const c of rows)html=html.replace(`<td><b>${esc(c.full_name)}</b></td>`,`<td><div class="customer-name"><span class="customer-avatar">${esc(c.full_name?.[0]||'K')}</span><b>${esc(c.full_name)}</b></div></td>`);return html};
function paging(count){return `<div class="pagination"><span>Hiển thị ${count} kết quả</span><b>1</b></div>`}
function adminHeading(name,subtitle,i,button=''){return `<div class="admin-page-head"><div><h1>${icon(i)}${name}</h1><p>${subtitle}</p></div>${button||'<select aria-label="Khoảng thời gian"><option>Toàn bộ dữ liệu</option></select>'}</div>`}
function metric(label,value,i='chart',note=''){return `<div class="metric-card">${icon(i)}<small>${label}</small><b>${value}</b>${note?`<em>${note}</em>`:''}</div>`}
function lineChart(months){if(!months.length)return '<div class="chart-empty">Chưa có dữ liệu doanh thu.<br>Biểu đồ sẽ xuất hiện khi có đơn hàng.</div>';const max=Math.max(1,...months.map(m=>m.revenue)),points=months.map((m,i)=>[35+i*500/Math.max(1,months.length-1),165-m.revenue/max*130]);const d=points.map((p,i)=>`${i?'L':'M'}${p[0]},${p[1]}`).join(' ');return `<svg class="revenue-line" viewBox="0 0 570 210" role="img" aria-label="Doanh thu từ đơn hàng theo tháng"><defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#83d7ad" stop-opacity=".7"/><stop offset="1" stop-color="#dff3e7" stop-opacity=".1"/></linearGradient></defs>${[35,78,122,165].map(y=>`<path d="M35 ${y}H550" stroke="#dfe9df" stroke-width="1"/>`).join('')}<path d="${d} L${points.at(-1)[0]},170 L35,170Z" fill="url(#chart-fill)"/><path d="${d}" fill="none" stroke="#159879" stroke-width="3"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="white" stroke="#159879" stroke-width="2"/><text x="${p[0]}" y="197" text-anchor="middle" fill="#345650" font-size="12">${esc(months[i].month)}</text>`).join('')}</svg>`}
function calendarCard(){const now=new Date(),y=now.getFullYear(),m=now.getMonth(),days=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7;return `<section class="card calendar-card"><h3>Tháng ${m+1}/${y}</h3><div class="calendar-grid">${['T2','T3','T4','T5','T6','T7','CN'].map(x=>`<b>${x}</b>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>`<span class="${i+1===now.getDate()?'today':''}">${i+1}</span>`).join('')}</div><p><i class="legend-dot"></i> Lịch hẹn đang quản lý</p>${petArt('grooming','calendar-pet')}</section>`}
const baseAdminPage=adminPage;
adminPage=async function(path){if(!STATE.user||STATE.user.role!=='admin')return baseAdminPage(path);const t=document.createElement('div');t.innerHTML=await baseAdminPage(path);const content=t.querySelector('.admin-content');if(!content)return t.innerHTML;const titles={'/admin/orders':['Đơn hàng','Quản lý và xử lý tất cả đơn hàng','cart'],'/admin/products':['Sản phẩm','Quản lý danh mục, thông tin và tồn kho sản phẩm','box'],'/admin/inventory':['Kho hàng','Quản lý tồn kho, nhập – xuất kho và cảnh báo tồn','home'],'/admin/customers':['Khách hàng','Quản lý thông tin, lịch sử mua hàng và chăm sóc khách hàng','user'],'/admin/promotions':['Khuyến mãi','Quản lý mã giảm giá, chương trình ưu đãi và chiến dịch','tag'],'/admin/appointments':['Dịch vụ & Lịch hẹn','Quản lý dịch vụ chăm sóc thú cưng và lịch hẹn khách hàng','calendar'],'/admin/reports':['Báo cáo','Thống kê, phân tích hiệu quả kinh doanh','chart'],'/admin/settings':['Cài đặt','Thiết lập thông tin cửa hàng, vận hành và phân quyền','settings']};const head=content.querySelector('.admin-page-head');if(head&&titles[path]){head.querySelector('h1').innerHTML=icon(titles[path][2])+titles[path][0];}
if(path==='/admin'||path==='/admin/'){
 const [d,r]=await Promise.all([api('/api/admin/dashboard'),api('/api/admin/reports')]);content.innerHTML=`${adminHeading('Tổng quan','Tổng hợp hoạt động kinh doanh của PawPaw Pet Shop','paw')}<div class="metric-grid">${metric('Doanh thu',money(d.revenue_vnd),'chart')}${metric('Đơn hàng',d.order_count,'cart',d.pending_count+' chờ xác nhận')}${metric('Khách hàng',d.customer_count,'user')}${metric('Yêu cầu đổi trả',r.returns_count,'refresh')}</div><div class="dashboard-columns"><div><section class="card"><div class="section-head"><h2>Biểu đồ doanh thu</h2><span class="pill green">Theo tháng</span></div>${lineChart(r.months)}</section><section class="card recent-orders"><div class="section-head"><h2>Đơn hàng gần nhất</h2>${link('/admin/orders','Xem tất cả →','text-link')}</div>${orderTable(d.latest_orders)}</section></div><aside><section class="card"><div class="section-head"><h2>Tồn kho thấp</h2>${link('/admin/inventory','Xem tất cả →','text-link')}</div>${d.low_stock.map(p=>`<div class="inventory-alert">${productArt(p)}<span>${esc(p.name)}</span><b class="danger">Còn: ${p.stock}</b></div>`).join('')||'<p>Chưa có cảnh báo tồn kho.</p>'}</section>${petArt('pet-duo','dashboard-pets')}</aside></div>`;
}
if(path==='/admin/orders'){const rows=await api('/api/admin/orders');const card=content.querySelector('.card');card.classList.add('orders-with-detail');card.insertAdjacentHTML('beforeend',`<aside class="order-detail-panel" id="admin-order-detail"><h3>Chi tiết đơn hàng</h3><p>Chọn một đơn hàng để xem thông tin và sản phẩm.</p></aside>${paging(rows.length)}`);content.querySelectorAll('tbody tr').forEach((tr,i)=>{if(rows[i]){tr.dataset.orderDetail=rows[i].id;tr.tabIndex=0;tr.setAttribute('aria-label','Xem đơn '+rows[i].order_code)}});window.pawpawAdminOrders=rows;}
if(path==='/admin/products'){const n=content.querySelectorAll('tbody tr').length;content.querySelector('.compact-metrics')?.remove();content.querySelector('.table-wrap')?.insertAdjacentHTML('beforeend',paging(n));}
if(path==='/admin/inventory'){const rows=await api('/api/admin/products');const table=content.querySelector('.table-wrap');table.insertAdjacentHTML('afterbegin','<div class="report-tabs"><b>Tồn kho hiện tại</b><span>Phiếu nhập kho</span><span>Phiếu xuất kho</span></div>');const container=document.createElement('div');container.className='inventory-columns';table.replaceWith(container);container.appendChild(table);container.insertAdjacentHTML('beforeend',`<aside class="card"><h3 class="danger">Cảnh báo tồn kho (${rows.filter(p=>p.stock<=12).length})</h3>${rows.filter(p=>p.stock<=12).map(p=>`<div class="inventory-alert">${productArt(p)}<span>${esc(p.name)}<small>Còn: ${p.stock}</small></span></div>`).join('')}<hr><h3>Thao tác nhập / xuất</h3><button class="btn btn-green full" data-action="inventory-adjust">${icon('box')}Điều chỉnh tồn kho</button></aside>`);}
if(path==='/admin/customers'){const rows=await api('/api/admin/customers');const table=content.querySelector('.card'),container=document.createElement('div');container.className='customer-columns';table.replaceWith(container);container.appendChild(table);container.insertAdjacentHTML('beforeend',`<aside class="card"><h3>Tổng quan khách hàng</h3>${metric('Tổng khách hàng',rows.length,'user')}<hr><h3>Các cấp bậc thành viên</h3><p>Kim cương</p><p>Vàng</p><p>Bạc</p><p>Thông thường</p><div class="member-donut" aria-hidden="true">${icon('paw')}</div></aside>`);table.insertAdjacentHTML('beforeend',paging(rows.length));}
if(path==='/admin/promotions'){content.querySelector('.card')?.insertAdjacentHTML('afterbegin','<div class="report-tabs"><b>Mã giảm giá</b><span>Chương trình ưu đãi</span><span>Chiến dịch</span></div>');content.querySelector('.card')?.insertAdjacentHTML('beforeend',paging(content.querySelectorAll('tbody tr').length));}
if(path==='/admin/appointments'){content.querySelector('.admin-page-head')?.insertAdjacentHTML('afterend','<div class="report-tabs"><b>Lịch hẹn</b><span>Dịch vụ</span><span>Nhân viên dịch vụ</span></div>');const card=content.querySelector('.card');const container=document.createElement('div');container.className='appointment-columns';card.replaceWith(container);container.innerHTML=calendarCard();container.appendChild(card);card.insertAdjacentHTML('afterbegin','<h3>Lịch hẹn của cửa hàng</h3>');container.insertAdjacentHTML('beforeend',`<aside class="card"><h3>Dịch vụ nổi bật</h3><div class="service-price">${icon('paw')}<span>Spa & Tắm<strong>149.000₫</strong></span></div><div class="service-price">${icon('shield')}<span>Tư vấn thú y<strong>99.000₫</strong></span></div>${petArt('vet-cat')}</aside>`);}
if(path==='/admin/reports'){const [r,d]=await Promise.all([api('/api/admin/reports'),api('/api/admin/dashboard')]);const total=r.months.reduce((s,x)=>s+x.revenue,0),count=r.months.reduce((s,x)=>s+x.orders,0);content.innerHTML=`${adminHeading('Báo cáo','Thống kê, phân tích hiệu quả kinh doanh','chart','<button class="btn btn-green" data-action="export-orders">↓ Xuất báo cáo</button>')}<div class="report-tabs"><b>Tổng quan</b><span>Doanh thu</span><span>Sản phẩm</span><span>Khách hàng</span><span>Dịch vụ</span></div><div class="metric-grid">${metric('Doanh thu',money(total),'chart')}${metric('Đơn hàng',count,'cart')}${metric('Giá trị đơn TB',money(count?Math.round(total/count):0),'tag')}${metric('Khách hàng',d.customer_count,'user')}</div><div class="admin-grid-two"><section class="card"><h3>Doanh thu theo thời gian</h3>${lineChart(r.months)}</section><section class="card"><h3>Sản phẩm bán chạy nhất</h3>${r.best_sellers.map(p=>`<div class="inventory-alert"><span>${esc(p.product_name)}</span><b>${p.units}</b></div>`).join('')||'<p class="empty-state">Chưa có giao dịch.</p>'}</section></div><div class="admin-grid-two"><section class="card"><h3>Danh mục sản phẩm</h3><div class="category-report"><div class="member-donut">${icon('paw')}</div><section>${d.categories.map(c=>`<p>${esc(c.category)} <b>${c.count}</b></p>`).join('')}</section></div></section><section class="card"><h3>Chỉ số khác</h3><div class="inventory-alert">Đơn chờ xác nhận <b>${d.pending_count}</b></div><div class="inventory-alert">Yêu cầu đổi trả <b>${r.returns_count}</b></div></section></div>`;}
if(path==='/admin/settings'){const form=content.querySelector('#settings-form'),wrap=document.createElement('div');wrap.className='settings-columns';form.replaceWith(wrap);wrap.innerHTML=`<aside class="card settings-nav">${[['home','Thông tin cửa hàng'],['truck','Vận chuyển'],['shield','Thanh toán'],['bell','Thông báo'],['user','Nhân sự & Phân quyền'],['settings','Hệ thống']].map((x,i)=>`<button type="button" class="${i?'':'active'}" ${i?'data-unavailable="Mục này cần kết nối thêm chức năng backend."':''}>${icon(x[0])}${x[1]}</button>`).join('')}</aside>`;wrap.appendChild(form);form.querySelector('.muted')?.remove();form.insertAdjacentHTML('afterbegin',`<div class="settings-brand">${brand()}<span>Thông tin cửa hàng</span></div>`);wrap.insertAdjacentHTML('beforeend',`<aside class="settings-aside">${petArt('pet-duo')}<section class="card"><h3>Thiết lập nhanh</h3><p>${icon('shield')}Bảo vệ tài khoản quản trị</p><p>${icon('truck')}Quản lý đơn tại cửa hàng</p><p>${icon('calendar')}Xác nhận lịch qua điện thoại</p></section></aside>`);}
return t.innerHTML;
};
function showOrderDetail(id){const o=window.pawpawAdminOrders?.find(x=>x.id===Number(id)),panel=document.querySelector('#admin-order-detail');if(!o||!panel)return;panel.innerHTML=`<div class="section-head"><h3>Chi tiết đơn hàng</h3><span class="status ${esc(o.status)}">${statusLabel(o.status)}</span></div><h3>#${esc(o.order_code)}</h3><small>Ngày đặt: ${esc(o.created_at)}</small><hr><h4>Thông tin khách hàng</h4><p>${icon('user')}${esc(o.customer_name)}</p><p>${icon('phone')}${esc(o.phone)}</p><p>${icon('pin')}${esc(o.address)}</p><hr><h4>Sản phẩm (${o.items.length})</h4>${o.items.map(p=>`<div class="detail-order-item"><span>${esc(p.product_name)} × ${p.quantity}</span><b>${money(p.unit_price_vnd*p.quantity)}</b></div>`).join('')}<hr><div class="detail-order-item"><span>Tạm tính</span><b>${money(o.subtotal_vnd)}</b></div><div class="detail-order-item"><span>Phí giao hàng</span><b>${money(o.shipping_vnd)}</b></div><div class="detail-order-item"><span>Giảm giá</span><b>-${money(o.discount_vnd)}</b></div><div class="summary-total"><span>Tổng thanh toán</span><b>${money(o.total_vnd)}</b></div>`;document.querySelectorAll('[data-order-detail]').forEach(tr=>tr.classList.toggle('selected',Number(tr.dataset.orderDetail)===o.id))}
// UI-only controls never pretend unavailable provider integrations have succeeded.
document.addEventListener('click',e=>{const gallery=e.target.closest('[data-gallery-src]');if(gallery){const stage=document.querySelector('.product-stage>img');if(stage){stage.src=gallery.dataset.gallerySrc;stage.className=gallery.dataset.gallerySrc.includes('lifestyle')?'pet-photo detail-lifestyle':'product-photo';}return}const unavailable=e.target.closest('[data-unavailable]');if(unavailable){toast(unavailable.dataset.unavailable);return}const toggle=e.target.closest('[data-password-toggle]');if(toggle){const input=toggle.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';toggle.setAttribute('aria-label',input.type==='password'?'Hiện mật khẩu':'Ẩn mật khẩu');toggle.setAttribute('aria-pressed',String(input.type==='text'));return}const order=e.target.closest('[data-order-detail]');if(order&&!e.target.closest('select,button'))showOrderDetail(order.dataset.orderDetail);if(e.target.closest('[data-faq-search]'))filterFAQ();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-order-detail]'))showOrderDetail(e.target.dataset.orderDetail)});
function filterFAQ(){const q=document.querySelector('#faq-search')?.value.toLocaleLowerCase('vi')||'';document.querySelectorAll('#faq-list details').forEach(el=>el.hidden=!el.textContent.toLocaleLowerCase('vi').includes(q))}
function applyCatalogFilters(){
 const panel=document.querySelector('#catalog-filters');if(!panel)return;
 const category=panel.querySelector('[name=category-filter]:checked')?.value||'Tất cả';
 const species=panel.querySelector('[name=species-filter]:checked')?.value||'Tất cả';
 const maxPrice=Number(panel.querySelector('#price-filter')?.value||1000000);
 const brands=[...panel.querySelectorAll('[name=brand-filter]:checked')].map(x=>x.value.toLowerCase());
 let visible=0;
 document.querySelectorAll('.catalog-products .product-card').forEach(el=>{
  const p=STATE.products.find(x=>x.id===Number(el.dataset.productId));if(!p)return;
  el.hidden=(category!=='Tất cả'&&p.category!==category)||(species!=='Tất cả'&&p.species!==species)||p.price_vnd>maxPrice||(brands.length>0&&!brands.some(b=>p.name.toLowerCase().includes(b)));
  if(!el.hidden)visible++;
 });
 const grid=document.querySelector('.catalog-products');if(!grid||!grid.querySelector('.product-card'))return;
 let empty=grid.querySelector('[data-filter-empty]');
 if(!empty){empty=document.createElement('p');empty.className='empty-state';empty.dataset.filterEmpty='';empty.textContent='Không tìm thấy sản phẩm phù hợp với bộ lọc.';grid.appendChild(empty)}
 empty.hidden=visible>0;
 const count=document.querySelector('.shop-title p');if(count)count.textContent=`Có ${visible} sản phẩm phù hợp`;
}
document.addEventListener('input',e=>{if(e.target.id==='faq-search')filterFAQ();if(e.target.id==='price-filter'){const label=document.querySelector('#price-filter-label');if(label)label.textContent=money(e.target.value);applyCatalogFilters()}});
document.addEventListener('change',e=>{if(e.target.form?.id!=='booking-form')return;const f=e.target.form,service=f.elements.serviceType.value,price=service==='vet'?99000:149000;document.querySelector('#booking-service-label').textContent=service==='vet'?'Tư vấn thú y':'Spa & Grooming';document.querySelector('#booking-price').textContent=money(price);document.querySelector('#booking-date-label').textContent=f.elements.serviceDate.value||'Chưa chọn';document.querySelector('#booking-time-label').textContent=f.elements.timeSlot.value;});
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-account-status]');if(!button)return;
 document.querySelectorAll('[data-account-status]').forEach(x=>{const active=x===button;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});
 let count=0;document.querySelectorAll('.account-order-card').forEach(card=>{card.hidden=!!button.dataset.accountStatus&&card.dataset.status!==button.dataset.accountStatus;if(!card.hidden)count++});
 const box=document.querySelector('#account-orders');let empty=box.querySelector('[data-order-empty]');
 if(!empty){empty=document.createElement('p');empty.dataset.orderEmpty='';empty.className='empty-state';empty.textContent='Không có đơn hàng ở trạng thái này.';box.appendChild(empty)}empty.hidden=count>0;
});
// Validate confirmation before the existing API submission listener handles registration.
document.addEventListener('submit',e=>{if(e.target.id!=='register-form')return;const f=e.target;if(f.elements.password.value!==f.elements.confirmPassword.value){e.preventDefault();e.stopImmediatePropagation();toast('Mật khẩu xác nhận chưa khớp.','error')}},true);
const originalAPI=api;
api=async function(path,options={}){const data=await originalAPI(path,options);if(path==='/api/orders'&&options.method==='POST'){try{sessionStorage.setItem('pawpaw-receipt',JSON.stringify({...data,created_at:new Date().toISOString()}))}catch{}}return data};
loadAccountOrders=async function(){try{const rows=await api('/api/account/orders'),box=document.querySelector('#account-orders');if(!box)return;box.innerHTML=rows.map(o=>`<article class="account-order-card" data-status="${esc(o.status)}"><div class="section-head"><b>#${esc(o.order_code)}</b><span class="status ${esc(o.status)}">${statusLabel(o.status)}</span></div><small>Ngày đặt: ${esc(o.created_at.slice(0,10))}</small><div class="account-order-products">${o.items.map(p=>{const product=STATE.products.find(x=>x.id===p.product_id||x.name===p.product_name);return `<span>${product?productArt(product):''}<span>${esc(p.product_name)} × ${p.quantity}</span></span>`}).join('')}</div><div class="account-order-total"><span>Tổng tiền: <b>${money(o.total_vnd)}</b></span>${link('/order?code='+encodeURIComponent(o.order_code),'Theo dõi đơn hàng','btn btn-light')}</div></article>`).join('')||'<p class="empty-state">Bạn chưa có đơn hàng nào.</p>'}catch(e){const box=document.querySelector('#account-orders');if(box)box.innerHTML=`<p>${esc(e.message)}</p>`}};
orderPage=function(){const code=new URLSearchParams(location.search).get('code');if(!code)return shell(`${bread('Tra cứu đơn hàng')}${titleRow('Tra cứu đơn hàng','','box')}<section class="card"><form id="lookup-form" class="inline-form"><input name="code" placeholder="Mã đơn hàng PP..." required><input name="phone" placeholder="Số điện thoại đặt hàng" required><button class="btn btn-green">Tra cứu</button></form><div id="order-result"></div></section>`);let receipt;try{receipt=JSON.parse(sessionStorage.getItem('pawpaw-receipt')||'null')}catch{}const ownReceipt=receipt?.order_code===code;return shell(`${bread('Đơn hàng')}<section class="receipt-hero"><div class="success-icon">✓</div><div><h1>${ownReceipt?'Đặt hàng thành công!':'Theo dõi đơn hàng'}</h1><p>${ownReceipt?'Cảm ơn bạn đã mua sắm tại PawPaw Pet Shop!<br>Đơn hàng đã được ghi nhận và đang chờ xác nhận.':'Nhập số điện thoại đặt hàng để xem trạng thái mới nhất.'}</p></div>${petArt('pet-blanket')}</section><section class="card receipt-meta"><div>Mã đơn hàng<strong>#${esc(code)}</strong></div>${ownReceipt?`<div>Ngày đặt hàng<b>${new Date(receipt.created_at).toLocaleString('vi-VN')}</b></div><div>Tổng thanh toán<strong>${money(receipt.total_vnd)}</strong></div><div>Phương thức thanh toán<b>Thanh toán khi nhận hàng (COD)</b></div>`:''}</section><section class="card receipt-tracking"><h2>${icon('box')}Theo dõi đơn hàng</h2>${ownReceipt?`<div class="receipt-steps"><div class="done"><b>✓</b><span>Đã đặt hàng</span></div><i></i><div><b>2</b><span>Đang xử lý</span></div><i></i><div><b>${icon('truck')}</b><span>Đang giao</span></div><i></i><div><b>4</b><span>Đã giao</span></div></div>`:''}<form id="lookup-form" class="inline-form"><input name="code" value="${esc(code)}" required aria-label="Mã đơn hàng"><input name="phone" placeholder="Số điện thoại để tra cứu" required><button class="btn btn-green">Xem chi tiết đơn hàng</button></form><div id="order-result"></div></section><div class="receipt-actions">${link('/support','Cần hỗ trợ?','btn btn-light')}${link('/shop','Tiếp tục mua sắm →','btn btn-green')}</div>`)};
// Combine filters against stable product IDs, including a subset of favorites.
document.addEventListener('click',e=>{
 const action=e.target.closest('[data-action]')?.dataset.action;
 if(!document.querySelector('#catalog-filters')||!['apply-filters','clear-filters'].includes(action))return;
 e.preventDefault();e.stopImmediatePropagation();
 if(action==='clear-filters'){
  const panel=document.querySelector('#catalog-filters');
  panel.querySelectorAll('[type=checkbox]').forEach(x=>x.checked=false);
  panel.querySelectorAll('[type=radio]').forEach(x=>x.checked=x.value==='Tất cả');
  panel.querySelector('#price-filter').value='1000000';
  panel.querySelector('#price-filter-label').textContent=money(1000000);
  if(location.pathname==='/shop'){navigate('/shop');return}
 }
 if(location.pathname==='/shop'){
  const params=new URLSearchParams(location.search);const panel=document.querySelector('#catalog-filters');
  for(const [name,key] of [['category-filter','category'],['species-filter','species']]){const value=panel.querySelector(`[name=${name}]:checked`)?.value;if(value&&value!=='Tất cả')params.set(key,value);else params.delete(key)}
  params.set('maxPrice',panel.querySelector('#price-filter').value);params.delete('brand');panel.querySelectorAll('[name=brand-filter]:checked').forEach(x=>params.append('brand',x.value));
  navigate('/shop?'+params);return;
 }
 applyCatalogFilters();closeDrawers();
},true);
document.addEventListener('change',e=>{if(e.target.matches('[name=brand-filter],[name=category-filter],[name=species-filter]'))applyCatalogFilters()});
function mobileNavigation(){const path=location.pathname;return `<nav class="mobile-bottom-nav" aria-label="Điều hướng nhanh">${[['/','home','Trang chủ'],['/shop','box','Sản phẩm'],['/favorites','heart','Yêu thích'],[STATE.user?'/account':'/login','user','Tài khoản']].map(x=>link(x[0],icon(x[1])+`<span>${x[2]}</span>`,path===x[0]?'active':'')).join('')}</nav><button class="mobile-scrim" type="button" data-close-drawers aria-label="Đóng menu và bộ lọc"></button>`}
function closeDrawers(){document.body.classList.remove('menu-open','filters-visible');document.querySelectorAll('[data-menu-toggle],[data-filter-toggle]').forEach(x=>x.setAttribute('aria-expanded','false'))}
document.addEventListener('click',e=>{if(e.target.closest('[data-menu-toggle]')){const open=document.body.classList.toggle('menu-open');document.body.classList.remove('filters-visible');document.querySelector('[data-menu-toggle]')?.setAttribute('aria-expanded',String(open));return}if(e.target.closest('[data-filter-toggle]')){const open=document.body.classList.toggle('filters-visible');document.body.classList.remove('menu-open');document.querySelectorAll('[data-filter-toggle]').forEach(x=>x.setAttribute('aria-expanded',String(open)));return}if(e.target.closest('[data-close-drawers]'))closeDrawers();if(e.target.closest('a[data-route]'))closeDrawers()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawers()});window.addEventListener('popstate',closeDrawers);
const renderPresentation=render;
render=async function(){closeDrawers();await renderPresentation();document.body.dataset.page=location.pathname;if(document.querySelector('#catalog-filters'))applyCatalogFilters();};
init();
